package fraymus.workspace;
import org.json.*;
import java.nio.file.*;
import java.util.*;
final class WorldNativeCheckpoint {
 static final String VERSION="native-pose-checkpoint-035-v1";
 private static final class Identity {static final String VALUE=compute();}
 static String identity(){return Identity.VALUE;}
 private static String compute(){var s=new StringBuilder(VERSION).append(ContactCheckpoint.identity());for(Class<?> t:new Class<?>[]{WorldPlan.class,WorldPhysics.class,WorldVerify.class,WorldNativeStore.class,WorldNativeCheckpoint.class,WorldFrames.class,WorldLedger.class,Construction051.class,Construction054.class})try(var in=t.getResourceAsStream(t.getSimpleName()+".class")){s.append(MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}s.append(WorldFrames.hash(Construction054.protocol()));return MeasurementStore.hash(s.toString());}
 static JSONObject write(Path file,JSONObject payload) throws Exception {var envelope=new JSONObject().put("version",VERSION).put("payload",payload).put("sha256",MeasurementStore.hash(MapCheckpoint.canonical(payload)));Files.createDirectories(file.getParent());var pending=file.resolveSibling(file.getFileName()+".pending");try(var channel=java.nio.channels.FileChannel.open(pending,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var b=java.nio.ByteBuffer.wrap(envelope.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));while(b.hasRemaining())channel.write(b);channel.force(true);}Files.move(pending,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);return envelope;}
 static JSONObject read(Path file,String id,JSONObject scene) throws Exception {if(Files.size(file)>32_000_000)throw new IllegalStateException("Pose checkpoint exceeds bounded trace size");var envelope=new JSONObject(Files.readString(file));var p=envelope.getJSONObject("payload");if(!envelope.getString("version").equals(VERSION)||!envelope.getString("sha256").equals(MeasurementStore.hash(MapCheckpoint.canonical(p))))throw new IllegalStateException("Pose checkpoint checksum/version mismatch");if(!p.getString("codeSha256").equals(identity()))throw new IllegalStateException("Pose checkpoint implementation changed");var run=p.getJSONObject("run");var state=p.getJSONObject("physics");if(!run.getString("id").equals(id)||!SpatialStore.binding(scene).similar(run.getJSONObject("plan").getJSONObject("intent").getJSONObject("binding")))throw new IllegalStateException("Pose checkpoint source/run changed");WorldPlan.verify(scene,run.getJSONObject("plan"));int tick=state.getInt("tick");var c=state.getJSONObject("controller");if(tick<0||tick>WorldPhysics.MAX_TICKS||!Set.of("start","move","release-settle","finished").contains(c.getString("phase"))||c.getInt("goal")<0||c.getInt("goal")>run.getJSONObject("plan").getJSONArray("orderedTargets").length()||c.getInt("stage")<0||c.getInt("stage")>3)throw new IllegalStateException("Pose checkpoint controller bounds changed");var samples=run.getJSONArray("samples");var expected=samples.isEmpty()?run.getJSONObject("initialState"):samples.getJSONObject(samples.length()-1);if(!expected.similar(state))throw new IllegalStateException("Pose checkpoint differs from exact committed trace");var ids=new HashSet<String>();for(Object raw:scene.getJSONArray("objects")){var o=(JSONObject)raw;if(o.getDouble("massKg")>0)ids.add(o.getString("id"));}if(state.getJSONArray("bodies").length()!=ids.size())throw new IllegalStateException("Pose checkpoint lost a dynamic body");for(Object raw:state.getJSONArray("bodies")){var b=(JSONObject)raw;if(!ids.remove(b.getString("id")))throw new IllegalStateException("Duplicate/foreign checkpoint body");for(String key:List.of("position","velocity","angularVelocity"))SpatialScene.vector(b.getJSONArray(key),100);WorldVerify.quaternion(b.getJSONArray("rotation"));}if(!c.getString("grippingId").isEmpty())SpatialScene.object(scene,c.getString("grippingId"));return envelope;}
}
